using System;
using System.Data;
using InformationWebObject;

namespace InformationCMS.Controls.LandingPage
{
    /// <summary>
    /// Truy cập INFO_LandingPage qua stored procedure (DAL mỏng trong CMS).
    /// </summary>
    public static class LandingPageService
    {
        public static DataTable Search(string keyword)
        {
            INFO_Information info = new INFO_Information();
            return info.GetDataTable("INFO_LandingPage_SearchCMS", "@KeyWord", keyword ?? "");
        }

        public static DataTable GetById(int pageId)
        {
            INFO_Information info = new INFO_Information();
            return info.GetDataTable("INFO_LandingPage_GetByIDCMS", "@PageID", pageId);
        }

        public static DataTable GetBySlug(string slug)
        {
            INFO_Information info = new INFO_Information();
            return info.GetDataTable("INFO_LandingPage_GetBySlug", "@Slug", slug ?? "");
        }

        public static int Save(
            int pageId,
            string title,
            string slug,
            string description,
            string keyword,
            string htmlBody,
            string cssText,
            string pageJson,
            bool isPublished,
            int sortOrder,
            string createdUser,
            string updatedUser)
        {
            INFO_Information info = new INFO_Information();
            object pageIdParam = pageId > 0 ? (object)pageId : DBNull.Value;

            DataTable dt = info.GetDataTable(
                "INFO_LandingPage_SaveCMS",
                "@PageID", pageIdParam,
                "@Title", title ?? "",
                "@Slug", slug ?? "",
                "@Description", string.IsNullOrEmpty(description) ? (object)DBNull.Value : description,
                "@Keyword", string.IsNullOrEmpty(keyword) ? (object)DBNull.Value : keyword,
                "@HtmlBody", htmlBody ?? "",
                "@CssText", string.IsNullOrEmpty(cssText) ? (object)DBNull.Value : cssText,
                "@PageJson", string.IsNullOrEmpty(pageJson) ? (object)DBNull.Value : pageJson,
                "@IsPublished", isPublished ? 1 : 0,
                "@SortOrder", sortOrder,
                "@CreatedUser", string.IsNullOrEmpty(createdUser) ? (object)DBNull.Value : createdUser,
                "@UpdatedUser", string.IsNullOrEmpty(updatedUser) ? (object)DBNull.Value : updatedUser
            );

            if (pageId > 0)
                return pageId;

            if (dt != null && dt.Rows.Count > 0 && dt.Columns.Contains("PageID"))
                return Convert.ToInt32(dt.Rows[0]["PageID"]);

            return 0;
        }

        public static bool Delete(int pageId)
        {
            INFO_Information info = new INFO_Information();
            info.GetDataTable("INFO_LandingPage_DeleteCMS", "@PageID", pageId);
            return true;
        }
    }
}

using System;
using System.Data;
using System.Web.UI;
using System.Web.UI.WebControls;
using DCore;
using WebGlobal;

namespace InformationCMS.Controls.LandingPage
{
    public partial class Edit : WebGlobal.ControlBase
    {
        #region Variables & Properties

        private string strListPage = "~/landing-page.html";
        private string strRelatePage = "~/landing-page-sua.html";
        private int intPageID = 0;

        public string ListPage
        {
            get { return strListPage; }
            set { strListPage = value; }
        }

        public string RelatePage
        {
            get { return strRelatePage; }
            set { strRelatePage = value; }
        }

        public int LandingPageID
        {
            get { return intPageID; }
            set { intPageID = value; }
        }

        public string GetUploadHandlerUrl()
        {
            return ResolveUrl("~/UploadLandingImage.ashx");
        }

        #endregion

        #region Permissions

        protected String strPermissionView = "CMS_LandingPage_View";
        protected String strPermissionAddEdit = "CMS_LandingPage_AddEdit";
        protected String strPermissionDelete = "CMS_LandingPage_Delete";

        #endregion

        #region Page Events

        protected void Page_Load(object sender, EventArgs e)
        {
            LoadQueryString();

            if (!IsPostBack)
            {
                SetPermission();

                if (intPageID > 0)
                    LoadInfo();
                else
                    ClearControls(true);
            }
        }

        #endregion

        #region Support Functions

        private void SetPermission()
        {
            if (!User.IsPermission(strPermissionView)
                && !User.IsPermission(strPermissionAddEdit)
                && !User.IsPermission(strPermissionDelete))
            {
                Session[DCore.Globals.ERROR] = new SystemError("Bạn không được phép truy cập chức năng này", null, ReturnPage);
                Response.Redirect("~/" + MessagePage);
            }

            pnlSaveButtons.Visible = User.IsPermission(strPermissionAddEdit);
        }

        private void ClearControls(bool bolIsClearOptionControl)
        {
            txtSlug.Text = "";
            txtTitle.Text = "";
            txtDescription.Text = "";
            txtKeyword.Text = "";
            txtCssText.Text = "";
            txtHtmlBody.Text = "";
            hdnPageJson.Value = "";
            txtSortOrder.Text = "0";

            if (bolIsClearOptionControl)
            {
                chkIsActive.Checked = true;
            }
        }

        private void LoadInfo()
        {
            if (this.intPageID <= 0)
                return;

            try
            {
                DataTable dt = LandingPageService.GetById(this.intPageID);
                if (dt == null || dt.Rows.Count < 1)
                {
                    MessageManager.ShowErrorMessage(Page, "Không tìm thấy landing page.");
                    return;
                }

                DataRow row = dt.Rows[0];
                txtSlug.Text = Convert.ToString(row["Slug"]);
                txtTitle.Text = Convert.ToString(row["Title"]);
                txtDescription.Text = row["Description"] == DBNull.Value ? "" : Convert.ToString(row["Description"]);
                txtKeyword.Text = row["Keyword"] == DBNull.Value ? "" : Convert.ToString(row["Keyword"]);
                txtHtmlBody.Text = row["HtmlBody"] == DBNull.Value ? "" : Convert.ToString(row["HtmlBody"]);
                txtCssText.Text = row["CssText"] == DBNull.Value ? "" : Convert.ToString(row["CssText"]);
                hdnPageJson.Value = row["PageJson"] == DBNull.Value ? "" : Convert.ToString(row["PageJson"]);
                chkIsActive.Checked = Convert.ToBoolean(row["IsPublished"]);
                txtSortOrder.Text = row["SortOrder"] == DBNull.Value ? "0" : Convert.ToString(row["SortOrder"]);
            }
            catch (Exception ex)
            {
                MessageManager.ShowErrorMessage(Page, "Lỗi tải dữ liệu!<br>" + ex.Message);
            }
        }

        private bool SaveData()
        {
            try
            {
                int sortOrder = 0;
                int.TryParse(txtSortOrder.Text, out sortOrder);

                string htmlBody = txtHtmlBody.Text ?? "";
                if (string.IsNullOrWhiteSpace(htmlBody))
                    htmlBody = "";

                int savedId = LandingPageService.Save(
                    intPageID,
                    txtTitle.Text.Trim(),
                    txtSlug.Text.Trim(),
                    txtDescription.Text.Trim(),
                    txtKeyword.Text.Trim(),
                    htmlBody,
                    txtCssText.Text,
                    hdnPageJson.Value,
                    chkIsActive.Checked,
                    sortOrder,
                    intPageID < 1 ? User.UserName : null,
                    intPageID > 0 ? User.UserName : null
                );

                if (savedId < 1)
                {
                    MessageManager.ShowErrorMessage(Page, "Lưu thất bại!");
                    return false;
                }

                this.intPageID = savedId;
                return true;
            }
            catch (Exception ex)
            {
                MessageManager.ShowErrorMessage(Page, "Lỗi!<br>" + ex.Message);
                return false;
            }
        }

        private void LoadQueryString()
        {
            if (Request["id"] != null)
            {
                int id = 0;
                if (int.TryParse(Request["id"], out id))
                    this.intPageID = id;
            }
        }

        #endregion

        #region Control Events

        protected void btnSaveAndBack_Click(object sender, EventArgs e)
        {
            if (SaveData())
            {
                Response.Redirect(ResolveUrl(ListPage));
            }
        }

        protected void btnSave_Click(object sender, EventArgs e)
        {
            if (SaveData())
            {
                bool bolIsAddNew = Request["id"] == null || Request["id"] == "";
                if (bolIsAddNew)
                {
                    Response.Redirect(ResolveUrl(RelatePage) + "?id=" + intPageID.ToString());
                }
                else
                {
                    LoadInfo();
                }
            }
        }

        protected void btnSaveAndAddNew_Click(object sender, EventArgs e)
        {
            if (SaveData())
            {
                Response.Redirect(ResolveUrl(RelatePage));
            }
        }

        protected void btnReturn_Click(object sender, EventArgs e)
        {
            Response.Redirect(ResolveUrl(ListPage));
        }

        #endregion
    }
}

using System;
