namespace InformationCMS.Controls.LandingPage
{
    public partial class List : ControlBase
    {
        #region Properties

        private string strEditPage = "~/landing-page-sua.html";
        public string EditPage
        {
            get { return strEditPage; }
            set { strEditPage = value; }
        }

        #endregion

        #region Permissions

        protected String strPermissionView = "CMS_LandingPage_View";
        protected String strPermissionAddEdit = "CMS_LandingPage_AddEdit";
        protected String strPermissionDelete = "CMS_LandingPage_Delete";

        #endregion

        #region Page Events

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                SetPermission();
                GridDatabind();
            }
        }

        #endregion

        #region Support Functions

        private void SetPermission()
        {
            if (!User.IsPermission(strPermissionView)
                && !User.IsPermission(strPermissionAddEdit)
                && !User.IsPermission(strPermissionDelete))
            {
                Session[DCore.Globals.ERROR] = new SystemError("Bạn không được phép truy cập chức năng này", null, ReturnPage);
                Response.Redirect("~/" + MessagePage);
            }

            btnAddNew.Visible = User.IsPermission(strPermissionAddEdit);
        }

        private void GridDatabind()
        {
            try
            {
                DataTable dtbData = LandingPageService.Search(txtSearch.Text.Trim());

                if (dtbData != null && dtbData.Rows.Count > 0)
                {
                    DataView dvw = new DataView(dtbData);

                    if (Session["LandingPage_SortExpression"] != null && Session["LandingPage_SortDirection"] != null)
                    {
                        string sortExpr = Session["LandingPage_SortExpression"].ToString();
                        SortDirection sortDir = (SortDirection)Enum.Parse(typeof(SortDirection), Session["LandingPage_SortDirection"].ToString());
                        dvw.Sort = sortExpr + (sortDir == SortDirection.Ascending ? " ASC" : " DESC");
                    }

                    grvObject.DataSource = dvw;
                }
                else
                {
                    grvObject.DataSource = null;
                }

                grvObject.DataBind();
                udpList.Update();
            }
            catch (Exception ex)
            {
                MsgBox.ShowError("Lỗi: " + ex.Message);
            }
        }

        #endregion

        #region Control Events

        protected void btnSearch_Click(object sender, EventArgs e)
        {
            GridDatabind();
        }

        protected void btnAddNew_Click(object sender, EventArgs e)
        {
            Response.Redirect(ResolveUrl(EditPage));
        }

        protected void grvObject_Sorting(object sender, GridViewSortEventArgs e)
        {
            Session["LandingPage_SortExpression"] = e.SortExpression;

            if (Session["LandingPage_SortDirection"] == null)
                Session["LandingPage_SortDirection"] = SortDirection.Descending;
            else
            {
                SortDirection sortDirection = (SortDirection)Enum.Parse(typeof(SortDirection), Session["LandingPage_SortDirection"].ToString());
                Session["LandingPage_SortDirection"] = sortDirection == SortDirection.Ascending ? SortDirection.Descending : SortDirection.Ascending;
            }

            GridDatabind();
        }

        protected void grvObject_RowCommand(object sender, GridViewCommandEventArgs e)
        {
            try
            {
                int pageID = Convert.ToInt32(e.CommandArgument);

                if (e.CommandName == "CopyItem")
                {
                    DataTable dt = LandingPageService.GetById(pageID);
                    if (dt == null || dt.Rows.Count < 1)
                    {
                        MsgBox.ShowError("Không tìm thấy landing page để sao chép.");
                        return;
                    }

                    DataRow row = dt.Rows[0];
                    int newId = LandingPageService.Save(
                        0,
                        Convert.ToString(row["Title"]) + " (Bản sao)",
                        Convert.ToString(row["Slug"]) + "-copy-" + DateTime.Now.ToString("yyyyMMddHHmmss"),
                        row["Description"] == DBNull.Value ? "" : Convert.ToString(row["Description"]),
                        row["Keyword"] == DBNull.Value ? "" : Convert.ToString(row["Keyword"]),
                        row["HtmlBody"] == DBNull.Value ? "" : Convert.ToString(row["HtmlBody"]),
                        row["CssText"] == DBNull.Value ? "" : Convert.ToString(row["CssText"]),
                        row["PageJson"] == DBNull.Value ? "" : Convert.ToString(row["PageJson"]),
                        false,
                        row["SortOrder"] == DBNull.Value ? 0 : Convert.ToInt32(row["SortOrder"]),
                        User.UserName,
                        null
                    );

                    if (newId > 0)
                    {
                        MsgBox.ShowSuccess("Sao chép landing page thành công.");
                        GridDatabind();
                    }
                    else
                    {
                        MsgBox.ShowError("Sao chép thất bại.");
                    }
                }
                else if (e.CommandName == "EditItem")
                {
                    Response.Redirect(ResolveUrl(EditPage) + "?id=" + pageID);
                }
                else if (e.CommandName == "DeleteItem")
                {
                    if (LandingPageService.Delete(pageID))
                    {
                        MsgBox.ShowSuccess("Xóa landing page thành công.");
                        GridDatabind();
                    }
                    else
                    {
                        MsgBox.ShowError("Không thể xóa landing page.");
                    }
                }
            }
            catch (Exception ex)
            {
                MsgBox.ShowError("Lỗi: " + ex.Message);
            }
        }

        #endregion
    }
}

