using System;
using System.Data;
using System.Web;
using System.Web.UI;
using InformationCMS.Controls.LandingPage;

namespace InformationCMS.Pages.LandingPage
{
    public partial class LandingPageView : Page
    {
        protected void Page_Load(object sender, EventArgs e)
        {
            if (IsPostBack)
                return;

            string slug = Request["slug"];
            if (string.IsNullOrEmpty(slug))
                slug = Request.QueryString["slug"];

            if (string.IsNullOrWhiteSpace(slug))
            {
                Response.StatusCode = 404;
                Response.End();
                return;
            }

            slug = slug.Trim().ToLowerInvariant();

            try
            {
                DataTable dt = LandingPageService.GetBySlug(slug);
                if (dt == null || dt.Rows.Count < 1)
                {
                    Response.StatusCode = 404;
                    Response.End();
                    return;
                }

                DataRow row = dt.Rows[0];
                string title = Convert.ToString(row["Title"]);
                string description = row["Description"] == DBNull.Value ? "" : Convert.ToString(row["Description"]);
                string keyword = row["Keyword"] == DBNull.Value ? "" : Convert.ToString(row["Keyword"]);
                string htmlBody = row["HtmlBody"] == DBNull.Value ? "" : Convert.ToString(row["HtmlBody"]);
                string cssText = row["CssText"] == DBNull.Value ? "" : Convert.ToString(row["CssText"]);

                Page.Title = title;

                if (!string.IsNullOrEmpty(description))
                {
                    litMetaDescription.Text = string.Format(
                        "<meta name=\"description\" content=\"{0}\" />",
                        HttpUtility.HtmlAttributeEncode(description)
                    );
                }

                if (!string.IsNullOrEmpty(keyword))
                {
                    litMetaKeyword.Text = string.Format(
                        "<meta name=\"keywords\" content=\"{0}\" />",
                        HttpUtility.HtmlAttributeEncode(keyword)
                    );
                }

                if (!string.IsNullOrEmpty(cssText))
                {
                    litCss.Text = string.Format("<style type=\"text/css\">{0}</style>", cssText);
                }

                litBody.Text = htmlBody;
            }
            catch
            {
                Response.StatusCode = 500;
                Response.End();
            }
        }
    }
}

